script:
// Aszinkron (indukciós) motor – kalickás forgórész
// Induction motor – squirrel-cage rotor
// Közelítő helyettesítő kapcsolás fázisonként, csillagkapcsolás / approximate equivalent circuit per phase, star:
//   s = (nₛ − n) / nₛ       Ī₂' = Ū_f / ((R₁ + R₂'/s) + jX)       Īₘ = Ū_f / (jXₘ)       Ī₁ = Ī₂' + Īₘ
//   M = 3·I₂'²·R₂' / (s·ωₛ)       J·dω/dt = M − M_t
// X és Xₘ 50 Hz-re értendő, a frekvenciával arányosan nő. / X and Xₘ are given at 50 Hz and scale with f.

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Aszinkron motor", en: "Induction motor"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (change it on the Speed slider)
timeScale(0.002);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(0.5);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("U",  {hu: "Vonali feszültség U", en: "Line voltage U"}, 0, 500, 400, 1, "V");
param("f",  {hu: "Frekvencia f", en: "Frequency f"}, 5, 100, 50, 1, "Hz");
param("p",  {hu: "Póluspárok száma p", en: "Pole pairs p"}, 1, 4, 2, 1, "");
param("R1", {hu: "Állórész-ellenállás R₁", en: "Stator resistance R₁"}, 0.1, 10, 1.4, 0.05, "Ω");
param("R2", {hu: "Forgórész-ellenállás R₂'", en: "Rotor resistance R₂'"}, 0.1, 10, 1.2, 0.05, "Ω");
param("X",  {hu: "Szórási reaktancia X₁ + X₂'", en: "Leakage reactance X₁ + X₂'"}, 0.5, 20, 4.4, 0.1, "Ω");
param("Xm", {hu: "Mágnesező reaktancia Xₘ", en: "Magnetising reactance Xₘ"}, 10, 200, 60, 1, "Ω");
// {keys: "w s"}: a W növeli, az S csökkenti a terhelést (nyomva tartva folyamatosan, Shift = 10×) / W raises, S lowers the load (smoothly while held, Shift = 10×)
param("ML", {hu: "Terhelőnyomaték M_t", en: "Load torque M_L"}, 0, 80, 20, 0.5, "N·m", {keys: "w s"});
// Legördülő lista: [érték, felirat] párok / Drop-down list: [value, label] pairs
choice("load", {hu: "Terhelés jellege", en: "Load type"},
  [["c", {hu: "állandó nyomaték", en: "constant torque"}], ["fan", {hu: "ventilátor (∝ n²)", en: "fan (∝ n²)"}]], "c");
param("J",  {hu: "Tehetetlenségi nyomaték J", en: "Moment of inertia J"}, 0.01, 1, 0.05, 0.01, "kg·m²");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("rev", {hu: "Forgásirány-váltás (L2 ↔ L3)", en: "Reverse rotation (L2 ↔ L3)"}, false, {key: "v"});   // V billentyű / V key
toggle("vec", {hu: "Mágneses mezővektorok", en: "Magnetic field vectors"}, true);
// Gomb a Vezérlők fülön / Button on the Controls tab
button({hu: "Indítás álló helyzetből", en: "Start from standstill"}, reset, {key: "Enter"});   // Enter billentyű / Enter key

const PH = [C.L1, C.L2, C.L3];
const sx = 300, sy = 320;   // a gép középpontja / machine centre
const NB = 18;              // forgórészrudak / rotor bars
let th = 0, thr = 0, wr = 0;   // ωt, forgórész szöge és szögsebessége / rotor angle and speed

function machine(w) {       // w: forgórész szögsebessége / rotor speed [rad/s]
  const sg = P.rev ? -1 : 1;                     // a mező forgásiránya / field direction
  const ws = sg * 2 * PI * P.f / P.p;            // szinkron szögsebesség / synchronous speed
  let s = (ws - w) / ws;
  if (abs(s) < 1e-6) s = s < 0 ? -1e-6 : 1e-6;
  const kf = P.f / 50, Uf = P.U / sqrt(3), U = complex(Uf, 0);
  const I2 = U.div(complex(P.R1 + P.R2 / s, P.X * kf));
  const Im = U.div(complex(0, P.Xm * kf));
  const I1 = I2.add(Im);
  const M = sg * 3 * I2.abs() ** 2 * P.R2 / (s * abs(ws));
  return {sg, ws, s, kf, Uf, I1, I2, Im, M};
}
// Terhelőnyomaték: állandó vagy n²-tel arányos (ventilátor) / load torque: constant or ∝ n² (fan)
function loadTorque(w, M) {
  const ws = 2 * PI * P.f / P.p;
  const T = P.load === "fan" ? P.ML * (w / ws) ** 2 : P.ML;
  if (abs(w) < 1e-3 && abs(M) <= T) return M;    // áll / stalled
  return T * sign(w || M);
}

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  // 10 allépés a pontosabb integráláshoz / 10 sub-steps for accuracy
  const n = 10, h = dt / n;
  for (let k = 0; k < n; k++) {
    const r = machine(wr);
    wr += (r.M - loadTorque(wr, r.M)) / P.J * h;
    thr += wr * h;
  }
  th += 2 * PI * P.f * dt;
});

// Forgórész-feszültség és -áram nyila: a teljes hossz (280 px) az álló forgórészhez tartozik
// Rotor voltage and current arrows: full length (280 px) belongs to the rotor at standstill
boundArrow("E2-nyíl", {
  x: 600, y: 532, angle: 0,                      // kezdőpont, irány: jobbra / start point, direction: right
  length: "280 * E2 / Uf",                       // E₂ = s·E₂₀ → felpörgéskor rövidül / shrinks during run-up
  width: 4, color: "#7c5cd6",
  label: "E₂"
});
boundArrow("I2-nyíl", {
  x: 600, y: 562, angle: 0,
  length: "280 * I2 / I2s",                      // az indítási áramhoz viszonyítva / relative to the starting current
  width: "2 + 4 * I2 / I2s",                     // nagy áramnál vastagabb / thicker at high current
  color: "#2e9e6a",                              // szín kis áramnál / colour at low current
  colorBy: "I2 / I2s", colorMin: 0.2, colorMax: 1,
  colorTo: "#d64045",                            // szín indításkor / colour at start
  label: "I₂'"
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  // A gép állapota a mostani fordulatszámon / machine state at the present speed
  const r = machine(wr);
  const axes = P.rev ? [0, deg(240), deg(120)] : [0, deg(120), deg(240)];
  const i1 = phases(sqrt(2) * r.I1.abs(), th, r.I1.arg());   // állórészáramok / stator currents
  const im = phases(sqrt(2) * r.Im.abs(), th, r.Im.arg());   // mágnesező áram / magnetising current
  // Háromfázisú állórész; a vezetőkben ⊙/⊗ az áram iránya / Three-phase stator; ⊙/⊗ shows the current direction
  stator3(sx, sy, {p: P.p, i: i1, imax: sqrt(2) * max(r.I1.abs(), 1e-9), axes: axes});

  // Mezők: B₁ az állórészáramból, Bδ a mágnesezőáramból (légrés), B₂ = Bδ − B₁ a forgórészé
  // Fields: B₁ from stator current, Bδ from magnetising current (air gap), B₂ = Bδ − B₁ from the rotor
  const B1 = fieldVec(i1, axes), Bd = fieldVec(im, axes);
  const B2 = {x: Bd.x - B1.x, y: Bd.y - B1.y};
  B2.mag = hypot(B2.x, B2.y); B2.angle = atan2(B2.y, B2.x);

  // Kalickás forgórész: a rúdáram ott a legnagyobb (⊙), ahol B₂ irányától 90°-kal előrébb járunk
  // Cage rotor: bar current peaks (⊙) 90° ahead of the rotor field axis
  circle(sx, sy, 165, {fill: "#c9ced6", stroke: "#9aa3b1", lw: 1.5});
  for (let j = 0; j < NB; j++) {
    const b = thr + j * 2 * PI / NB;
    const ib = cos(P.p * b - (B2.angle + PI / 2));
    current(sx + 145 * cos(b), sy - 145 * sin(b), abs(ib) > 0.15 && B2.mag > 1e-6 ? sign(ib) : 0, 9,
            {stroke: C.copper, lw: 2, alpha: 0.3 + 0.7 * abs(ib)});
  }
  circle(sx, sy, 42, {fill: "#9aa3b1"});
  line(sx, sy, sx + 42 * cos(thr), sy - 42 * sin(thr), {stroke: C.ink, lw: 3});   // tengelyjel / shaft mark

  if (P.vec) {
    const k = 135 / max(B1.mag, B2.mag, Bd.mag, 1e-9);   // közös lépték / common scale
    for (let m = 0; m < P.p; m++) {
      const off = 2 * PI * m / P.p, lab = m === 0;
      phasor(sx, sy, B1.mag * k, (B1.angle + off) / P.p, {stroke: C.blue, lw: 3}, lab ? "B₁" : "");
      phasor(sx, sy, B2.mag * k, (B2.angle + off) / P.p, {stroke: C.copper, lw: 3}, lab ? "B₂" : "");
      phasor(sx, sy, Bd.mag * k, (Bd.angle + off) / P.p, {stroke: C.red, lw: 4}, lab ? "Bδ" : "");
    }
  }
  circle(sx, sy, 8, {fill: C.ink});

  // ── M(n) jelleggörbe / torque–speed curve ──
  const ns = 60 * P.f / P.p, nNow = abs(wr) * 30 / PI;
  const gx = 590, gb = 400, gw = 370, gh = 250, nTop = ns * 1.1;
  // M(n) görbe a helyettesítő kapcsolásból / M(n) curve from the equivalent circuit
  const curve = [];
  for (let j = 0; j <= 120; j++) {
    const n = nTop * j / 120;
    curve.push([n, r.sg * machine(r.sg * n * PI / 30).M]);
  }
  const Mtop = max(...curve.map(c => c[1]), P.ML * 1.1, 1);
  const X = n => gx + n / nTop * gw, Y = M => gb - max(M, -0.15 * Mtop) / Mtop * gh;   // a generátoros ág levágva / generator branch clipped
  arrow(gx, gb, gx + gw + 18, gb, {stroke: C.gray, lw: 1.2, head: 8, id: "tengelyek"});
  arrow(gx, gb + 30, gx, gb - gh - 25, {stroke: C.gray, lw: 1.2, head: 8, id: "tengelyek"});
  text("n [1/min]", gx + gw + 6, gb + 22, {size: 12, color: C.gray, align: "right"});
  text("M [N·m]", gx + 8, gb - gh - 14, {size: 12, color: C.gray});
  line(X(ns), gb - 5, X(ns), gb + 5, {stroke: C.gray, lw: 1.2});
  text("nₛ = " + fmt(ns, 0), X(ns), gb + 20, {size: 12, color: C.gray, align: "center"});
  text(fmt(Mtop, 0), gx - 6, Y(Mtop) + 4, {size: 11, color: C.gray, align: "right"});
  line(gx - 3, Y(Mtop), gx + 3, Y(Mtop), {stroke: C.gray, lw: 1});
  const lc = curve.map(([n]) => [X(n), Y(P.load === "fan" ? P.ML * (n / ns) ** 2 : P.ML)]);
  polyline(lc, {stroke: C.orange, lw: 2, dash: [6, 4]});
  polyline(curve.map(([n, M]) => [X(n), Y(M)]), {stroke: C.blue, lw: 2.5});
  circle(X(min(nNow, nTop)), Y(r.sg * r.M), 6, {fill: C.red, stroke: "#fff", lw: 1.5});
  text({hu: "M(n) – motor", en: "M(n) – motor"}, gx + 12, gb - gh + 8, {size: 13, color: C.blue, bold: true});
  text({hu: "terhelés", en: "load"}, gx + 12, gb - gh + 26, {size: 13, color: C.orange, bold: true});

  text("s = " + fmt(r.s * 100, 1) + " %      n = " + fmt(r.sg * wr * 30 / PI, 0) + " 1/min", 775, 470, {size: 18, align: "center", bold: true});
  text({hu: "forgórész-frekvencia f₂ = s·f = ", en: "rotor frequency f₂ = s·f = "}, 775, 500, {size: 15, align: "right", color: C.gray});
  text(fmt(abs(r.s) * P.f, 2) + " Hz", 778, 500, {size: 15, color: C.gray});

  // ── Mért értékek / readouts ──
  const Xk = P.X * r.kf;
  // Billenő szlip és billenőnyomaték / breakdown slip and breakdown torque
  const sk = P.R2 / sqrt(P.R1 ** 2 + Xk ** 2);
  const Mk = 3 * r.Uf ** 2 / (2 * abs(r.ws) * (P.R1 + sqrt(P.R1 ** 2 + Xk ** 2)));
  const r0 = machine(0);
  const Pin = 3 * r.Uf * r.I1.re, Pm = r.M * wr;
  val({s: r.s, E2: abs(r.s) * r.Uf, Uf: r.Uf, I1: r.I1.abs(), I2: r.I2.abs(), I2s: r0.I2.abs(), M: r.sg * r.M, n: nNow});   // a Jelölők fülnek / for the Markup tab
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Szinkron fordulatszám nₛ = 60·f/p", en: "Synchronous speed nₛ = 60·f/p"}, ns, "1/min");
  show({hu: "Fordulatszám n", en: "Speed n"}, nNow, "1/min");
  show({hu: "Szlip s", en: "Slip s"}, r.s * 100, "%");
  show({hu: "Állórészáram I₁", en: "Stator current I₁"}, r.I1.abs(), "A");
  show({hu: "Indítási áram (s = 1)", en: "Starting current (s = 1)"}, r0.I1.abs(), "A");
  show({hu: "Nyomaték M", en: "Torque M"}, r.sg * r.M, "N·m");
  show({hu: "Indítónyomaték", en: "Starting torque"}, r.sg * r0.M, "N·m");
  show({hu: "Billenőnyomaték M_b", en: "Breakdown torque M_b"}, Mk, "N·m");
  show({hu: "Billenő szlip s_b", en: "Breakdown slip s_b"}, sk * 100, "%");
  show({hu: "Felvett teljesítmény P₁", en: "Input power P₁"}, Pin, "W");
  show({hu: "Leadott teljesítmény P₂ = M·ω", en: "Output power P₂ = M·ω"}, Pm, "W");
  show({hu: "Hatásfok η", en: "Efficiency η"}, Pin > 1 && Pm > 0 ? Pm / Pin * 100 : "—", "%");
  show("cos φ", Pin / max(3 * r.Uf * r.I1.abs(), 1e-9), "");

  for (let j = 0; j < 3; j++) plot("i" + "₁₂₃"[j], i1[j], {unit: "A", color: PH[j], group: "i"});
  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Fordulatszám n", en: "Speed n"}, nNow, {unit: "1/min", color: C.blue, min: 0});
  plot({hu: "Nyomaték M", en: "Torque M"}, r.sg * r.M, {unit: "N·m", color: C.red});
});
